1	// Package credit 实现本地课程学分与免修的登记、持久化与核对。
2	//
3	// 基本对象：
4	//   - 学生（Student）：以唯一编号登记；
5	//   - 课程（Course）：唯一编号、名称、正整数学分，初始开放，可停开/恢复；
6	//   - 课程要求（Requirement）：属于某名学生，编号在该学生名下唯一，指向一门课程；
7	//   - 修读（Enrollment）：属于某名学生的一项要求，记录学期与编号，结果为
8	//     选课/通过/未通过；
9	//   - 免修（Waiver）：明确指向该学生的一项要求，带编号与非空依据，状态为
10	//     有效/已拒绝/已撤销。
11	//
12	// 所有“重复登记相同内容”的操作都幂等：返回原记录、不新增数据；内容冲突的
13	// 重复请求一律拒绝并保留原记录。
14	package credit
15	
16	import (
17		"errors"
18		"fmt"
19		"math"
20		"strings"
21	)
22	
23	// Result 是修读结果。
24	type Result string
25	
26	const (
27		// Enrolled 已选课、尚未有结果，不计学分。
28		Enrolled Result = "enrolled"
29		// Passed 通过。
30		Passed Result = "passed"
31		// Failed 未通过，不计学分。
32		Failed Result = "failed"
33	)
34	
35	// WaiverStatus 是免修申请的状态。
36	type WaiverStatus string
37	
38	const (
39		// WaiverApproved 有效免修：满足对应要求并获得课程学分。
40		WaiverApproved WaiverStatus = "approved"
41		// WaiverRejected 已拒绝：申请内容与拒绝原因保留在免修历史中。
42		WaiverRejected WaiverStatus = "rejected"
43		// WaiverRevoked 已撤销：原依据保留，要求按修读情况重新判定。
44		WaiverRevoked WaiverStatus = "revoked"
45	)
46	
47	// Course 课程：编号唯一，学分为正整数。
48	type Course struct {
49		ID     string `json:"id"`
50		Name   string `json:"name"`
51		Credit int    `json:"credit"`
52		Open   bool   `json:"open"`
53	}
54	
55	// Student 学生：只有唯一编号。
56	type Student struct {
57		ID string `json:"id"`
58	}
59	
60	// Requirement 课程要求：在所属学生名下编号唯一，指向一门已登记课程。
61	type Requirement struct {
62		ID        string `json:"id"`
63		StudentID string `json:"student"`
64		CourseID  string `json:"course"`
65	}
66	
67	// Enrollment 修读：属于某名学生的一项要求，编号在该学生名下唯一。
68	type Enrollment struct {
69		ID        string `json:"id"`
70		StudentID string `json:"student"`
71		ReqID     string `json:"req"`
72		Term      string `json:"term"`
73		Result    Result `json:"result"`
74		// ResultSeq 是首次提交结果的先后序号，用于确定“最先提交的通过记录”。
75		ResultSeq int `json:"resultSeq,omitempty"`
76	}
77	
78	// Waiver 免修申请。被拒绝或撤销后记录仍保留在免修历史中。
79	type Waiver struct {
80		ID        string       `json:"id"`
81		StudentID string       `json:"student"`
82		ReqID     string       `json:"req"`
83		Basis     string       `json:"basis"`
84		Status    WaiverStatus `json:"status"`
85		// Reason 记录拒绝原因或撤销原因。
86		Reason string `json:"reason,omitempty"`
87	}
88	
89	// Store 是全部记录的内存集合，零值即可用。
90	type Store struct {
91		courses      []*Course
92		students     []*Student
93		requirements []*Requirement
94		enrollments  []*Enrollment
95		waivers      []*Waiver
96	
97		courseByID    map[string]*Course
98		studentByID   map[string]*Student
99		reqByKey      map[ownerKey]*Requirement // (student, reqID)
100		reqByDup      map[ownerKey]string       // (student, course) -> reqID
101		enrByKey      map[ownerKey]*Enrollment  // (student, enrID)
102		waiverByKey   map[ownerKey]*Waiver      // (student, waiverID)
103		nextResultSeq int
104		// dirty 记录自加载以来是否发生过需要落盘的变更（新建被拒绝的免修也算）。
105		dirty bool
106	}
107	
108	// ownerKey 是“所属学生编号 + 该学生名下编号”的复合键。两部分各自按完整
109	// 文字参与比较，因此要求是否存在必须以所属学生和编号都完全一致为准。
110	// 不能用 student + "\x00" + id 之类的字符串拼接：JSON 解码后的编号本身
111	// 允许包含 U+0000 等任意字符，拼接键会把 ("s","x\x00r") 与 ("s\x00x","r")
112	// 两项不同学生的记录混成同一键，导致合法文件被判重复或免修借用他人要求。
113	type ownerKey struct {
114		student string
115		id      string
116	}
117	
118	func reqKey(student, id string) ownerKey { return ownerKey{student, id} }
119	func dupKey(student, course string) ownerKey {
120		return ownerKey{student, course}
121	}
122	
123	// blankBasis 报告一份免修依据是否不含任何实际文字：空字符串，或全部由空白
124	// 字符组成。空白按 Unicode 判定，除空格、制表符、换行、回车外还包括全角
125	// 空格（U+3000）、不换行空格（U+00A0）等，混合使用这些字符仍算没有依据。
126	//
127	// 该判定只用于读取校验，绝不修剪或改写已保存的依据原文——依据中含有实际
128	// 文字时，其前后与中间原有的空白必须原样保留在免修历史中。
129	func blankBasis(basis string) bool {
130		return strings.TrimSpace(basis) == ""
131	}
132	
133	func newStore() *Store {
134		s := &Store{}
135		s.resetIndexes()
136		return s
137	}
138	
139	func (s *Store) resetIndexes() {
140		s.courseByID = map[string]*Course{}
141		s.studentByID = map[string]*Student{}
142		s.reqByKey = map[ownerKey]*Requirement{}
143		s.reqByDup = map[ownerKey]string{}
144		s.enrByKey = map[ownerKey]*Enrollment{}
145		s.waiverByKey = map[ownerKey]*Waiver{}
146	}
147	
148	// NewStore 返回空记录集。
149	func NewStore() *Store { return newStore() }
150	
151	// Dirty 报告自加载以来是否发生过需要落盘的变更。
152	// 被拒绝但要保留在免修历史中的申请也计为变更；纯幂等返回与只读核对不计。
153	func (s *Store) Dirty() bool { return s.dirty }
154	
155	// ---------- 查询 ----------
156	
157	// Course 按编号返回课程；不存在返回 nil。
158	func (s *Store) Course(id string) *Course { return s.courseByID[id] }
159	
160	// Courses 按登记顺序返回全部课程。
161	func (s *Store) Courses() []*Course { return append([]*Course(nil), s.courses...) }
162	
163	// Student 按编号返回学生；不存在返回 nil。
164	func (s *Store) Student(id string) *Student { return s.studentByID[id] }
165	
166	// Students 按登记顺序返回全部学生。
167	func (s *Store) Students() []*Student { return append([]*Student(nil), s.students...) }
168	
169	// Requirement 返回某学生名下的要求；不存在（包括要求属于其他学生）返回 nil。
170	func (s *Store) Requirement(student, reqID string) *Requirement {
171		return s.reqByKey[reqKey(student, reqID)]
172	}
173	
174	// Requirements 返回某学生的全部要求（按登记顺序）；学生不存在返回 nil。
175	func (s *Store) Requirements(student string) []*Requirement {
176		if _, ok := s.studentByID[student]; !ok {
177			return nil
178		}
179		var out []*Requirement
180		for _, r := range s.requirements {
181			if r.StudentID == student {
182				out = append(out, r)
183			}
184		}
185		return out
186	}
187	
188	// AllRequirements 按登记顺序返回全部要求。
189	func (s *Store) AllRequirements() []*Requirement {
190		return append([]*Requirement(nil), s.requirements...)
191	}
192	
193	// Enrollment 返回某学生名下的修读；不存在返回 nil。
194	func (s *Store) Enrollment(student, id string) *Enrollment {
195		return s.enrByKey[reqKey(student, id)]
196	}
197	
198	// Enrollments 返回某学生的全部修读（按登记顺序）；学生不存在返回 nil。
199	func (s *Store) Enrollments(student string) []*Enrollment {
200		if _, ok := s.studentByID[student]; !ok {
201			return nil
202		}
203		var out []*Enrollment
204		for _, e := range s.enrollments {
205			if e.StudentID == student {
206				out = append(out, e)
207			}
208		}
209		return out
210	}
211	
212	// Waiver 返回某学生名下的免修申请；不存在返回 nil。
213	func (s *Store) Waiver(student, id string) *Waiver {
214		return s.waiverByKey[reqKey(student, id)]
215	}
216	
217	// Waivers 返回某学生的全部免修历史（按申请顺序）；学生不存在返回 nil。
218	func (s *Store) Waivers(student string) []*Waiver {
219		if _, ok := s.studentByID[student]; !ok {
220			return nil
221		}
222		var out []*Waiver
223		for _, w := range s.waivers {
224			if w.StudentID == student {
225				out = append(out, w)
226			}
227		}
228		return out
229	}
230	
231	// ---------- 学生 ----------
232	
233	// AddStudent 登记学生。编号已存在时原样返回已有学生且 action=existed（幂等）。
234	//
235	// 学生编号按用户给出的完整文字参与查找与保存，前后空白（普通空格、制表符、
236	// 全角空格 U+3000、不换行空格 U+00A0 等）也是编号内容，绝不修剪：记录文件
237	// 可以合法保存 “s1” 与 “ s1 ” 两名独立学生，登记与重复判断必须命中编号
238	// 完全一致的那一名，并保留编号原文。文件里只有 “s1” 时提交 “ s1 ” 一律
239	// 新建，绝不借用去掉空白后能碰上的另一名学生的课程要求、修读、免修或学分；
240	// 再次提交某个完整编号时只判断对应学生：命中则返回原记录（幂等），不新增
241	// 副本、不改动记录文件，也不移动或合并两名学生各自名下编号相同的要求、
242	// 修读与免修历史。已有合法文件中的带空白编号继续按原文使用，登记不能把
243	// 它们改名，也不能为匹配输入重写其他记录的学生归属。
244	// 编号为空字符串，或全部由空白字符组成（普通空格、制表符、全角空格、
245	// 不换行空格等，允许混用）时直接拒绝，不创建学生；含实际文字的编号原样
246	// 保存。这与登记课程要求、选课、提交成绩、免修、核对、查询使用的对象
247	// 完全一致。
248	func (s *Store) AddStudent(id string) (st *Student, action Action, err error) {
249		if id == "" {
250			return nil, "", errors.New("学生编号不能为空")
251		}
252		if strings.TrimSpace(id) == "" {
253			return nil, "", errors.New("学生编号不能为空")
254		}
255		if existing := s.studentByID[id]; existing != nil {
256			return existing, ActionExisted, nil
257		}
258		st = &Student{ID: id}
259		s.students = append(s.students, st)
260		s.studentByID[id] = st
261		s.dirty = true
262		return st, ActionCreated, nil
263	}
264	
265	// ---------- 课程 ----------
266	
267	// Action 描述登记类操作相对已有记录做了什么。
268	type Action string
269	
270	const (
271		// ActionCreated 新建了记录。
272		ActionCreated Action = "created"
273		// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
274		ActionExisted Action = "existed"
275		// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
276		ActionUpdated Action = "updated"
277	)
278	
279	// AddCourse 登记课程，学分为正整数，新课程初始开放。
280	// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
281	// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
282	// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
283	//
284	// 课程编号按用户给出的完整文字参与匹配与保存，前后空白（普通空格、制表符、
285	// 全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存 “c1” 与 “ c1 ”
286	// 两门独立课程，登记与重复判断必须命中编号完全一致的那一门，并保留编号原文。
287	// 完整编号找不到时一律新建，绝不借用去掉空白后能碰上的另一门课程的名称、
288	// 学分或停开/开放状态；再次提交某个完整编号时只判断对应课程：名称与学分
289	// 相同则返回原记录，内容不同仍按上述规则更新对应课程，不新增副本、不改动
290	// 另一门课程。学分锁定跟随实际命中的课程：只有要求引用了该完整编号的课程
291	// 时才禁止修改它的学分，另一门同号不同空白课程是否被引用与此无关。
292	// 编号为空字符串，或全部由空白字符组成（普通空格、制表符、全角空格等，
293	// 允许混用）时直接拒绝；含实际文字的编号原样保存。课程名称沿用现有输入
294	// 规则：前后空白不计入名称内容，修剪后为空则拒绝。
295	func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
296		name = strings.TrimSpace(name)
297		if id == "" {
298			return nil, "", errors.New("课程编号不能为空")
299		}
300		if strings.TrimSpace(id) == "" {
301			return nil, "", errors.New("课程编号不能只由空白字符组成")
302		}
303		if name == "" {
304			return nil, "", errors.New("课程名称不能为空")
305		}
306		if credit <= 0 {
307			return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
308		}
309		if existing := s.courseByID[id]; existing != nil {
310			if existing.Name == name && existing.Credit == credit {
311				return existing, ActionExisted, nil
312			}
313			if existing.Credit != credit && s.courseReferenced(id) {
314				return nil, "", fmt.Errorf(
315					"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
316					id, existing.Credit)
317			}
318			existing.Name = name
319			existing.Credit = credit
320			s.dirty = true
321			return existing, ActionUpdated, nil
322		}
323		c = &Course{ID: id, Name: name, Credit: credit, Open: true}
324		s.courses = append(s.courses, c)
325		s.courseByID[id] = c
326		s.dirty = true
327		return c, ActionCreated, nil
328	}
329	
330	// courseReferenced 报告课程是否被任何学生的课程要求引用。
331	func (s *Store) courseReferenced(id string) bool {
332		for _, r := range s.requirements {
333			if r.CourseID == id {
334				return true
335			}
336		}
337		return false
338	}
339	
340	// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
341	func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
342		c := s.courseByID[id]
343		if c == nil {
344			return nil, fmt.Errorf("课程 %s 不存在", id)
345		}
346		if c.Open != open {
347			c.Open = open
348			s.dirty = true
349		}
350		return c, nil
351	}
352	
353	// ---------- 课程要求 ----------
354	
355	// AddRequirement 为学生登记一项指向课程的要求。
356	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
357	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
358	//
359	// 学生编号、要求编号与课程编号按用户给出的完整文字参与匹配，前后空白
360	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
361	// 合法保存 “s1” 与 “ s1 ” 两名学生、“c1” 与 “ c1 ” 两门课程、同一学生
362	// 名下 “r1” 与 “ r1 ” 两项要求，登记必须命中编号完全一致的学生与课程，
363	// 新要求也必须登记在完整编号的学生名下并保留完整编号。完整编号找不到
364	// 学生时报告学生不存在，完整编号找不到课程时报告课程不存在——即使去掉
365	// 空白能碰上另一名学生或另一门课程，也绝不借用那份记录，更不能自动创建
366	// 学生或课程。编号为空字符串时直接拒绝；要求编号只由空白字符组成时
367	// 不得建立。这与选课、免修、查询使用的对象完全一致：已有带空白编号的
368	// 合法记录继续按原样读取，不因登记而被改写、合并或重新解释。
369	// 课程是否停开不影响建立要求：新要求本身不带来学分，之后只有通过修读
370	// 或有效免修才能满足它。
371	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
372		if studentID == "" || reqID == "" || courseID == "" {
373			return nil, "", errors.New("学生编号、要求编号和课程编号不能为空")
374		}
375		if strings.TrimSpace(reqID) == "" {
376			return nil, "", errors.New("要求编号不能只由空白字符组成")
377		}
378		if _, ok := s.studentByID[studentID]; !ok {
379			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
380		}
381		c := s.courseByID[courseID]
382		if c == nil {
383			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
384		}
385		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
386			if existing.CourseID != courseID {
387				return nil, "", fmt.Errorf(
388					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
389					studentID, reqID, existing.CourseID, courseID)
390			}
391			return existing, ActionExisted, nil
392		}
393		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
394			return nil, "", fmt.Errorf(
395				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
396		}
397		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
398		s.requirements = append(s.requirements, r)
399		s.reqByKey[reqKey(studentID, reqID)] = r
400		s.reqByDup[dupKey(studentID, courseID)] = reqID
401		s.dirty = true
402		return r, ActionCreated, nil
403	}
404	
405	// ---------- 修读 ----------
406	
407	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
408	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
409	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
410	// （已登记记录的重复提交仍按幂等返回原记录）。
411	//
412	// 学生编号、要求编号与修读编号按用户给出的完整文字参与匹配，前后空白
413	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
414	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
415	// 要求、“e1” 与 “ e1 ” 两份修读，登记必须命中编号完全一致的对象，新
416	// 修读也必须登记在完整编号的学生与要求名下并保留完整编号。完整编号找
417	// 不到学生时报告学生不存在；学生存在但名下没有该完整要求编号时报告本人
418	// 名下没有该要求——即使去掉空白能碰上另一名学生或另一项要求，也绝不
419	// 借用那份记录，更不能把修读登记到别人名下。编号为空字符串时直接拒绝；
420	// 只由空白字符组成的修读编号不得建立。学期沿用现有输入规则：前后空白
421	// 不计入学期内容，修剪后为空则拒绝。
422	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
423		term = strings.TrimSpace(term)
424		if studentID == "" || reqID == "" || enrID == "" {
425			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
426		}
427		if strings.TrimSpace(enrID) == "" {
428			return nil, "", errors.New("修读编号不能只由空白字符组成")
429		}
430		if term == "" {
431			return nil, "", errors.New("学期不能为空")
432		}
433		if _, ok := s.studentByID[studentID]; !ok {
434			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
435		}
436		r := s.reqByKey[reqKey(studentID, reqID)]
437		if r == nil {
438			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
439		}
440		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
441			if existing.ReqID != reqID || existing.Term != term {
442				return nil, "", fmt.Errorf(
443					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
444					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
445			}
446			return existing, ActionExisted, nil
447		}
448		c := s.courseByID[r.CourseID]
449		if c == nil || !c.Open {
450			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
451		}
452		e = &Enrollment{
453			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
454		}
455		s.enrollments = append(s.enrollments, e)
456		s.enrByKey[reqKey(studentID, enrID)] = e
457		s.dirty = true
458		return e, ActionCreated, nil
459	}
460	
461	// SubmitResult 为修读提交通过/未通过结果。
462	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
463	// 一律拒绝并保留原记录。
464	//
465	// 首次提交结果会从全局递增计数器领取一个结果提交序号（ResultSeq），用于
466	// 记录多次提交的先后关系；通过与未通过都占用一次序号。计数器是整数类型
467	// int：当它已经达到该类型可表示的最大值（64 位环境下为
468	// 9223372036854775807）时，再递增必然回绕成负数并保存，会破坏整份记录
469	// （负序号、与原有序号的先后关系错乱、记录无法再正常读取）。因此计数已
470	// 到上限时，任何仍处于“选课”的修读都不能再首次提交结果：明确拒绝，不
471	// 改结果、不发序号、不标记变更；不会因该要求已有另一份通过修读或已有
472	// 有效免修而放行，也不能从小重新编号、借用历史空缺编号或改排已有成绩。
473	// 距上限恰好还差一时允许最后一次正常的首次提交，其先后关系照常保留；
474	// 未通过同样占用这最后一次机会且仍不计学分。已经提交过结果的修读不
475	// 需要新序号：重复提交相同结果仍幂等返回原记录，改提另一结果仍按冲突
476	// 规则拒绝。
477	//
478	// 学生编号与修读编号按用户给出的完整文字参与匹配，前后空白（普通空格、
479	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
480	// “s1”与“ s1 ”两名学生、同一学生名下“e1”与“ e1 ”两份修读，提交
481	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
482	// 学生存在但名下没有该完整修读编号时报告该修读不存在——即使去掉空白后
483	// 能碰上另一名学生或另一份修读，也绝不借用那份记录，更不能据此补建修读。
484	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
485		if result != Passed && result != Failed {
486			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
487		}
488		if _, ok := s.studentByID[studentID]; !ok {
489			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
490		}
491		e = s.enrByKey[reqKey(studentID, enrID)]
492		if e == nil {
493			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
494		}
495		if e.Result == result {
496			return e, false, nil
497		}
498		if e.Result != Enrolled {
499			return nil, false, fmt.Errorf(
500				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
501		}
502		// 首次提交必须领取新的结果序号。计数器已达 int 上限时不能再递增：
503		// MaxInt+1 会静默回绕成 MinInt 并随修读落盘，随后连原有记录都无法
504		// 正常读取。这里在改动任何状态之前拒绝，保持修读为选课、整份记录
505		// 原样不变。是否还能提交只取决于计数器本身：不重新从小编号、不
506		// 借用历史空缺编号，也不因该要求另有通过修读或有效免修而放行。
507		if s.nextResultSeq >= math.MaxInt {
508			return nil, false, fmt.Errorf(
509				"学生 %s 的修读 %s 不能提交成绩：成绩提交顺序编号已用尽（已达本程序整数类型最大值 %d），无法提交新的成绩，原记录保留",
510				studentID, enrID, math.MaxInt)
511		}
512		s.nextResultSeq++
513		e.Result = result
514		e.ResultSeq = s.nextResultSeq
515		s.dirty = true
516		return e, true, nil
517	}
518	
519	// ---------- 免修 ----------
520	
521	// ApplyWaiver 提交免修申请，依据必须含实际文字。
522	//
523	// 首次提交且内容合法：状态为有效（approved），action=created。
524	// 目标要求不存在（含要求属于其他学生）、依据不含实际文字、或该要求已有
525	// 有效免修：申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
526	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
527	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
528	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
529	//
530	// 学生编号、要求编号与免修编号按用户给出的完整文字参与匹配，前后空白
531	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
532	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
533	// 要求、“w1” 与 “ w1 ” 两份申请，提交必须命中编号完全一致的那一项，
534	// 申请也必须登记在完整编号的申请人名下。完整编号找不到学生时直接按业务
535	// 规则报错，不在任何学生名下新增历史；学生存在但名下没有该完整要求编号
536	// 时，即使去掉空白能碰上另一项要求，也绝不借用那份记录，而是按原规则在
537	// 申请人名下保存原要求编号、免修编号、依据原文与拒绝原因。编号为空字符串
538	// 时直接拒绝，不创建申请。依据含实际文字时其中的空白（包括前后空白）
539	// 原样保留；是否“没有依据”只按空白内容判定（见 blankBasis），绝不修剪
540	// 或改写依据原文。
541	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
542		if studentID == "" || reqID == "" || waiverID == "" {
543			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
544		}
545		if _, ok := s.studentByID[studentID]; !ok {
546			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
547		}
548		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
549			if existing.ReqID != reqID || existing.Basis != basis {
550				return nil, "", fmt.Errorf(
551					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
552					studentID, waiverID, existing.ReqID, existing.Basis)
553			}
554			return existing, ActionExisted, nil
555		}
556	
557		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
558		switch {
559		case s.reqByKey[reqKey(studentID, reqID)] == nil:
560			w.Status = WaiverRejected
561			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
562		case blankBasis(basis):
563			w.Status = WaiverRejected
564			w.Reason = "免修依据为空"
565		default:
566			if other := s.validWaiver(studentID, reqID); other != nil {
567				w.Status = WaiverRejected
568				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
569				break
570			}
571			w.Status = WaiverApproved
572		}
573		s.waivers = append(s.waivers, w)
574		s.waiverByKey[reqKey(studentID, waiverID)] = w
575		s.dirty = true
576		return w, ActionCreated, nil
577	}
578	
579	// validWaiver 返回某要求当前有效的免修。
580	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
581		for _, w := range s.waivers {
582			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
583				return w
584			}
585		}
586		return nil
587	}
588	
589	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
590	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
591	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
592	//
593	// 学生编号与免修编号按用户给出的完整文字参与匹配，前后空白（普通空格、
594	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
595	// “s1”与“ s1 ”两名学生、同一学生名下“w1”与“ w1 ”两份免修，撤销
596	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
597	// 学生存在但名下没有该完整免修编号时报告该免修不存在——即使去掉空白后
598	// 能碰上另一名学生或另一份免修，也绝不借用那份记录，更不能改写原编号、
599	// 合并申请或新增免修历史。撤销提示与免修历史一律使用实际命中的原编号。
600	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
601		reason = strings.TrimSpace(reason)
602		if _, ok := s.studentByID[studentID]; !ok {
603			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
604		}
605		w = s.waiverByKey[reqKey(studentID, waiverID)]
606		if w == nil {
607			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
608		}
609		switch w.Status {
610		case WaiverApproved:
611			w.Status = WaiverRevoked
612			if reason == "" {
613				reason = "手动撤销"
614			}
615			w.Reason = reason
616			s.dirty = true
617			return w, true, nil
618		case WaiverRevoked:
619			return w, false, nil
620		default:
621			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
622		}
623	}
624

