1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"reflect"
8		"strings"
9		"unicode/utf8"
10	)
11	
12	// duplicateFieldError 表示同一个 JSON 对象内出现了读取功能无法确定归属的
13	// 两个字段：
14	//   - 字段名完全相同（first == second，如两份 "credit"）；
15	//   - 两个字段名只有大小写差异（编码/json 的大小写折叠等同于
16	//     strings.EqualFold），却都被现有读取功能识别为同一条记录字段
17	//     （如 "credit" 与 "Credit" 都填入课程学分，"courses" 与
18	//     "COURSES" 都填入最外层课程列表）。
19	//
20	// field 是两者共同指向的规范字段名（结构体 json 标签原文）；完全同名时
21	// 与 first、second 相同。
22	type duplicateFieldError struct {
23		field  string
24		first  string
25		second string
26	}
27	
28	func (e *duplicateFieldError) Error() string {
29		if e.first == e.second {
30			return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.first)
31		}
32		return fmt.Sprintf(
33			"同一 JSON 对象内字段名 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定",
34			e.first, e.second, e.field)
35	}
36	
37	// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
38	// “能被现有读取功能识别”的字段名。
39	type objKind int
40	
41	const (
42		objUnknown     objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
43		objFile                       // 记录最外层 fileData
44		objCourse                     // courses 数组元素：课程
45		objStudent                    // students 数组元素：学生
46		objRequirement                // requirements 数组元素：课程要求
47		objEnrollment                 // enrollments 数组元素：修读
48		objWaiver                     // waivers 数组元素：免修
49	)
50	
51	// recordObjectTypes 把每类对象对应到它在记录格式中的结构体类型。各类对象
52	// “能被读取功能识别哪些字段名”只有结构体定义上的 json 标签这一个出处：
53	// 正常读取时 json.Decoder 按这些标签（先精确名、再大小写折叠名）填入字段，
54	// 重复字段扫描也从同一份结构体定义取字段名。调整一项记录的字段（增删、
55	// 改名、换标签）只需改结构体定义，正常读取与重复检查始终对“哪些字段可
56	// 识别、哪些写法指向同一字段”作出一致判断，不需要再同步另一份字段名称
57	// 清单。
58	var recordObjectTypes = map[objKind]reflect.Type{
59		objFile:        reflect.TypeOf(fileData{}),
60		objCourse:      reflect.TypeOf(Course{}),
61		objStudent:     reflect.TypeOf(Student{}),
62		objRequirement: reflect.TypeOf(Requirement{}),
63		objEnrollment:  reflect.TypeOf(Enrollment{}),
64		objWaiver:      reflect.TypeOf(Waiver{}),
65	}
66	
67	// jsonFieldName 按 encoding/json 的规则给出结构体字段被识别的 JSON 名称：
68	// 未导出字段不参与解码；json 标签为 "-" 的字段跳过（返回空串）；没有标签
69	// 时用 Go 字段名本身；omitempty 等选项不影响名称。记录结构体均为扁平字段，
70	// 无嵌入字段提升问题。
71	func jsonFieldName(sf reflect.StructField) string {
72		if sf.PkgPath != "" {
73			return ""
74		}
75		name := sf.Tag.Get("json")
76		if name == "-" {
77			return ""
78		}
79		if comma := strings.IndexByte(name, ','); comma >= 0 {
80			name = name[:comma]
81		}
82		if name == "" {
83			name = sf.Name
84		}
85		return name
86	}
87	
88	// recordFields 是各类对象能被读取功能识别的字段名（结构体 json 标签原文），
89	// 全部直接取自 recordObjectTypes 中的结构体定义，不在别处另列一份。
90	// 同一对象的字段名在大小写不敏感比较下必须两两不同——否则该格式本身就有
91	// 歧义（两个字段折叠到同一名称），在初始化阶段直接指出这类定义错误。
92	var recordFields = buildRecordFields()
93	
94	func buildRecordFields() map[objKind][]string {
95		m := make(map[objKind][]string, len(recordObjectTypes))
96		for kind, t := range recordObjectTypes {
97			names := make([]string, 0, t.NumField())
98			for i := 0; i < t.NumField(); i++ {
99				name := jsonFieldName(t.Field(i))
100				if name == "" {
101					continue
102				}
103				for _, other := range names {
104					if strings.EqualFold(name, other) {
105						panic(fmt.Sprintf(
106							"记录结构体 %s 的字段 %q 与 %q 在大小写折叠后同名，记录格式存在歧义",
107							t.Name(), name, other))
108					}
109				}
110				names = append(names, name)
111			}
112			m[kind] = names
113		}
114		return m
115	}
116	
117	// matchRecordField 报告键名 key 是否会被现有读取功能填入 kind 对象的某个
118	// 记录字段，命中时返回该字段的规范名称（json 标签原文）。
119	//
120	// encoding/json 解进结构体时先按精确名匹配，不中再按大小写折叠名匹配，
121	// 折叠规则等同于 strings.EqualFold（完整 Unicode 简单折叠，而非仅 ASCII：
122	// 例如 U+212A“K”折到 k、U+0130“İ”折到 i）。这里照搬同一判定，字段名又
123	// 直接来自结构体标签，才能保证“两个键名被现有读取功能识别为同一字段”的
124	// 口径与实际解码完全一致——任何大小写或 Unicode 转义组合都无法让一个键
125	// 绕过本扫描却仍被解码器接受。
126	func matchRecordField(kind objKind, key string) (string, bool) {
127		for _, tag := range recordFields[kind] {
128			if strings.EqualFold(key, tag) {
129				return tag, true
130			}
131		}
132		return "", false
133	}
134	
135	// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
136	// 记录格式里只有最外层的五个数组承载记录对象。归属同样直接由 fileData 的
137	// 结构体定义推导：键按大小写折叠命中哪个字段，就取该字段（切片取元素、
138	// 指针解引用）的类型再反查对象类型——courses 与 COURSES 解出来都是课程
139	// 列表，其元素必须按课程对象检查，不能借顶层键的大小写写法绕过限制；
140	// version 等非记录对象字段返回 objUnknown。
141	func fileKeyObjectKind(key string) objKind {
142		t := recordObjectTypes[objFile]
143		for i := 0; i < t.NumField(); i++ {
144			sf := t.Field(i)
145			name := jsonFieldName(sf)
146			if name == "" || !strings.EqualFold(name, key) {
147				continue
148			}
149			ft := sf.Type
150			if ft.Kind() == reflect.Slice {
151				ft = ft.Elem()
152			}
153			if ft.Kind() == reflect.Ptr {
154				ft = ft.Elem()
155			}
156			for kind, rt := range recordObjectTypes {
157				if rt == ft {
158					return kind
159				}
160			}
161			return objUnknown
162		}
163		return objUnknown
164	}
165	
166	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
167	// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
168	// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
169	//
170	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
171	// 后一个静默覆盖，而且结构体字段按大小写折叠匹配 json 标签（规则等同于
172	// strings.EqualFold）——同一门课程同时写 "credit":4 与 "Credit":9 时，
173	// 标准库读不出“曾经写过两个”，学分直接被后一个值顶替，两个键先后颠倒
174	// 结果也随之颠倒。因此在正常结构体解码之前先单独扫描一遍 token 流。
175	//
176	// 规则：
177	//   - 同一个 JSON 对象内字段归属只能确定一次：完全同名的两个键，或两个
178	//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
179	//     Credit、student 与 Student、courses 与 COURSES），发现即返回
180	//     *duplicateFieldError（含规范字段名与两个原始写法）。
181	//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
182	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
183	//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
184	//     两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
185	//     绕开限制。
186	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
187	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
188	//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
189	//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
190	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
191	func scanDuplicateKeys(r io.Reader) error {
192		type frame struct {
193			isObj bool
194			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
195			kind objKind
196			// elem 标识数组元素对象的类型（数组帧使用）。
197			elem objKind
198			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
199			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
200			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
201			// 借此区分字符串 token 是键还是普通字符串值。
202			expectKey bool
203			// pendingKey 是当前值所属的键，用于判断嵌套对象/数组的类型。
204			pendingKey string
205			// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
206			rawKeys map[string]struct{}
207			// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
208			// 字段名为索引；无法识别的键不进此表。
209			seen map[string]string
210		}
211		var stack []frame
212		depth := 0
213	
214		push := func(d json.Delim) {
215			switch d {
216			case '{':
217				kind := objUnknown
218				if n := len(stack); n == 0 {
219					// 第一份值的根对象即记录最外层；根值不是对象时结构体
220					// 解码阶段自会按类型拒绝。
221					kind = objFile
222				} else if p := &stack[n-1]; p.isObj {
223					if p.kind == objFile {
224						kind = fileKeyObjectKind(p.pendingKey)
225					}
226				} else {
227					// 对象在数组里：类型由承载它的数组决定（数组类型又由
228					// 最外层五个字段之一决定）。
229					kind = stack[n-1].elem
230				}
231				stack = append(stack, frame{
232					isObj: true, kind: kind, expectKey: true,
233					rawKeys: map[string]struct{}{},
234					seen:    map[string]string{},
235				})
236			case '[':
237				elem := objUnknown
238				if n := len(stack); n > 0 {
239					if p := &stack[n-1]; p.isObj {
240						if p.kind == objFile {
241							elem = fileKeyObjectKind(p.pendingKey)
242						}
243					} else {
244						// 数组嵌套：内层数组元素类型跟随外层数组。
245						elem = p.elem
246					}
247				}
248				stack = append(stack, frame{isObj: false, elem: elem})
249			}
250		}
251		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
252		valueEnded := func() {
253			if n := len(stack); n > 0 {
254				f := &stack[n-1]
255				if f.isObj && !f.expectKey {
256					f.expectKey = true
257					f.pendingKey = ""
258				}
259			}
260		}
261	
262		dec := json.NewDecoder(r)
263		for {
264			tok, err := dec.Token()
265			if err == io.EOF {
266				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
267				return nil
268			}
269			if err != nil {
270				return err
271			}
272			switch t := tok.(type) {
273			case json.Delim:
274				switch t {
275				case '{', '[':
276					depth++
277					push(t)
278				case '}', ']':
279					depth--
280					stack = stack[:len(stack)-1]
281					if depth == 0 {
282						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
283						return nil
284					}
285					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
286					valueEnded()
287				}
288			case string:
289				n := len(stack)
290				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
291					f := &stack[n-1]
292					// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义
293					// 形式的键名与直接写出的同名键在这里完全不可区分。
294					if _, dup := f.rawKeys[t]; dup {
295						return &duplicateFieldError{field: t, first: t, second: t}
296					}
297					f.rawKeys[t] = struct{}{}
298					// 只有指向同一条可识别记录字段的不同写法才算归属
299					// 冲突；未知键的大小写变体随后由结构体解码按未知字段
300					// 拒绝（如 "foo" 与 "Foo" 不会被当成任何业务字段）。
301					if canonical, known := matchRecordField(f.kind, t); known {
302						if prev, conflict := f.seen[canonical]; conflict {
303							return &duplicateFieldError{
304								field:  canonical,
305								first:  prev,
306								second: t,
307							}
308						}
309						f.seen[canonical] = t
310					}
311					f.expectKey = false
312					f.pendingKey = t
313					continue
314				}
315				valueEnded()
316				if depth == 0 {
317					return nil // 顶层标量值
318				}
319			default:
320				// number、bool、nil 等标量值。
321				valueEnded()
322				if depth == 0 {
323					return nil
324				}
325			}
326		}
327	}
328	
329	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
330	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
331	//   - 字符串中直接写入的字节必须是合法 UTF-8；
332	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
333	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
334	//
335	// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
336	// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
337	// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
338	// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
339	// 文件，整份判为内容损坏，哪怕问题只在一条已拒绝免修的依据里、或在与本次
340	// 核对无关的课程名称里。
341	//
342	// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
343	// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
344	// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
345	//
346	// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
347	// 本来就会被读取方拒绝，无需在此重复判定。
348	func scanStringUnicode(raw []byte) error {
349		i := 0
350		for i < len(raw) && isJSONSpace(raw[i]) {
351			i++
352		}
353		if i >= len(raw) {
354			return nil // 空输入交由后续结构体解码报错
355		}
356		switch raw[i] {
357		case '"':
358			// 顶层就是一个字符串：扫描它本身即可。
359			_, err := scanJSONString(raw, i)
360			return err
361		case '{', '[':
362		default:
363			return nil // 顶层标量（数字、true、false、null）不含字符串
364		}
365		depth := 0
366		for i < len(raw) {
367			switch raw[i] {
368			case '"':
369				j, err := scanJSONString(raw, i)
370				if err != nil {
371					return err
372				}
373				i = j
374			case '{', '[':
375				depth++
376				i++
377			case '}', ']':
378				depth--
379				i++
380				if depth == 0 {
381					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
382					return nil
383				}
384			default:
385				i++
386			}
387		}
388		return nil // 未闭合的结构由 JSON 解析报错
389	}
390	
391	// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
392	// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
393	// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
394	func scanJSONString(raw []byte, start int) (int, error) {
395		i := start + 1
396		for i < len(raw) {
397			c := raw[i]
398			switch {
399			case c == '"':
400				return i + 1, nil
401			case c == '\\':
402				if i+1 >= len(raw) {
403					return len(raw), nil
404				}
405				if raw[i+1] != 'u' {
406					i += 2 // 其他转义的合法性由 JSON 解析器校验
407					continue
408				}
409				v, ok := hex4(raw, i+2)
410				if !ok {
411					i += 2 // 非法 \u 转义形式由 JSON 解析器报错
412					continue
413				}
414				switch {
415				case isHighSurrogate(v):
416					// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
417					if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
418						if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
419							i += 12
420							continue
421						}
422					}
423					return 0, fmt.Errorf(
424						`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
425				case isLowSurrogate(v):
426					return 0, fmt.Errorf(
427						`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
428				default:
429					i += 6
430				}
431			case c < utf8.RuneSelf:
432				i++
433			default:
434				// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
435				// 是合法文字：只有解码失败（size 为 1）才拒绝。
436				r, size := utf8.DecodeRune(raw[i:])
437				if r == utf8.RuneError && size == 1 {
438					return 0, fmt.Errorf(
439						"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
440				}
441				i += size
442			}
443		}
444		return i, nil // 未闭合的字符串由 JSON 解析器报错
445	}
446	
447	func isJSONSpace(c byte) bool {
448		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
449	}
450	
451	func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
452	func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }
453	
454	// hex4 把 b[i:i+4] 读作四位十六进制数。
455	func hex4(b []byte, i int) (rune, bool) {
456		if i+4 > len(b) {
457			return 0, false
458		}
459		var v rune
460		for k := 0; k < 4; k++ {
461			c := b[i+k]
462			var d byte
463			switch {
464			case '0' <= c && c <= '9':
465				d = c - '0'
466			case 'a' <= c && c <= 'f':
467				d = c - 'a' + 10
468			case 'A' <= c && c <= 'F':
469				d = c - 'A' + 10
470			default:
471				return 0, false
472			}
473			v = v*16 + rune(d)
474		}
475		return v, true
476	}
477

