func TestZeroValueStoreUsable(t *testing.T) {
	var s Store
	// 使用前查询按空集合处理
	if got := s.Courses(); len(got) != 0 {
		t.Fatalf("courses not empty: %v", got)
	}
	if got := s.Students(); len(got) != 0 {
		t.Fatalf("students not empty: %v", got)
	}
	if s.Course("c1") != nil || s.Student("s1") != nil {
		t.Fatal("lookup on zero store should miss")
	}
	if s.Requirements("s1") != nil || s.Enrollments("s1") != nil || s.Waivers("s1") != nil {
		t.Fatal("per-student lists on zero store should be nil")
	}
	if s.Dirty() {
		t.Fatal("zero store should not be dirty")
	}
	// 不合法登记被拒绝且不产生变更
	if _, _, err := s.AddStudent("  "); err == nil {
		t.Fatal("blank student id should be rejected")
	}
	if _, _, err := s.AddCourse("c1", "", 0); err == nil {
		t.Fatal("invalid course should be rejected")
	}
	if s.Dirty() {
		t.Fatal("rejected adds must not mark dirty")
	}
	// 第一次合法登记：课程
	c, action, err := s.AddCourse("c1", "数学", 4)
	if err != nil || action != ActionCreated || !c.Open || c.Credit != 4 || c.Name != "数学" {
		t.Fatalf("AddCourse: %v %v %v", c, action, err)
	}
	// 随后登记学生，课程不能丢失
	st, action, err := s.AddStudent("s1")
	if err != nil || action != ActionCreated || st.ID != "s1" {
		t.Fatalf("AddStudent: %v %v %v", st, action, err)
	}
	if s.Course("c1") == nil || s.Student("s1") == nil {
		t.Fatal("objects lost after second kind registered")
	}
	// 要求、修读、成绩、学分
	if _, _, err := s.AddRequirement("s1", "r1", "c1"); err != nil {
		t.Fatalf("AddRequirement: %v", err)
	}
	if _, _, err := s.AddEnrollment("s1", "r1", "2026春", "e1"); err != nil {
		t.Fatalf("AddEnrollment: %v", err)
	}
	if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
		t.Fatalf("SubmitResult: %v", err)
	}
	rep := s.Report("s1")
	if rep.TotalCredits != 4 {
		t.Fatalf("credits = %d, want 4", rep.TotalCredits)
	}
	// 幂等与空白编号独立性
	if _, a, _ := s.AddStudent("s1"); a != ActionExisted {
		t.Fatal("duplicate student should be existed")
	}
	if _, a, err := s.AddStudent(" s1 "); err != nil || a != ActionCreated {
		t.Fatalf("whitespace-distinct student: %v %v", a, err)
	}
	if !s.Dirty() {
		t.Fatal("successful adds must mark dirty")
	}

	// 第一次登记也可以是学生
	var s2 Store
	if _, _, err := s2.AddStudent("s1"); err != nil {
		t.Fatalf("zero store first AddStudent: %v", err)
	}
	if _, _, err := s2.AddCourse("c1", "英语", 2); err != nil {
		t.Fatalf("zero store second AddCourse: %v", err)
	}
	if s2.Student("s1") == nil || s2.Course("c1") == nil {
		t.Fatal("objects lost")
	}
}
EOF
